import * as T from 'three';
import {GLTFLoader} from '/simulations/vendor/loaders/GLTFLoader.js';
import {OrbitControls} from '/simulations/vendor/OrbitControls.js';
import {sandboxWheel} from '/simulations/vendor/sandbox-camera.mjs';
const $=s=>document.querySelector(s),host=$('#viewport');
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;host.prepend(renderer.domElement);
const scene=new T.Scene();scene.add(new T.HemisphereLight('#fff6e7','#7b8266',2.2));const light=new T.DirectionalLight('#fff4df',3);light.position.set(-3,6,4);light.castShadow=true;light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-4,right:4,top:4,bottom:-4});light.shadow.normalBias=.015;scene.add(light);
const floor=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshStandardMaterial({roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.003;floor.receiveShadow=true;scene.add(floor);
const camera=new T.PerspectiveCamera(34,1,.01,100),orbit=new OrbitControls(camera,renderer.domElement);orbit.mouseButtons={LEFT:T.MOUSE.ROTATE,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.touches={ONE:T.TOUCH.ROTATE,TWO:T.TOUCH.DOLLY_PAN};orbit.minDistance=2;orbit.maxDistance=14;orbit.maxPolarAngle=Math.PI*.49;
renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();sandboxWheel(T,camera,orbit,e);},{capture:true,passive:false});
function fit(){orbit.target.set(0,1.15,0);const d=Math.min(13,Math.max(5.5,3.1/(2*Math.tan(34*Math.PI/360)*camera.aspect)));camera.position.copy(orbit.target).add(new T.Vector3(1.4,.8,6).normalize().multiplyScalar(d));orbit.update();}$('#fit').onclick=fit;
new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();fit();}).observe(host);
function theme(){const c=getComputedStyle(document.documentElement).getPropertyValue('--app-canvas').trim()||'#f4eddf';scene.background=new T.Color(c);floor.material.color.set(c);}window.addEventListener('app-style-change',theme);theme();
const names=['walk','idle 1','idle 2','idle 3','attack','defend','celebrate','perish','rest'];$('#clip').innerHTML=names.map(n=>`<option>${n}</option>`).join('');let model,mixer,action,clips,playing=true,token=0;
const singles=new Set(['attack','defend','celebrate','perish']);
function playClip(){if(!mixer)return;mixer.stopAllAction();const clip=clips.find(c=>c.name===$('#clip').value);if(!clip){$('#status').textContent='Clip unavailable';return;}action=mixer.clipAction(clip);action.reset();action.setLoop(singles.has(clip.name)?T.LoopOnce:T.LoopRepeat,Infinity);action.clampWhenFinished=true;action.play();playing=true;$('#play').textContent='Pause';$('#status').textContent=`${clip.name} · ${singles.has(clip.name)?'one shot · holds final pose':'loop'}`;mixer.update(0);}
async function load(){const id=++token;$('#status').textContent='Loading…';try{const g=await new GLTFLoader().loadAsync(`/greek-animation-a-assets/${$('#character').value}.glb`);if(id!==token)return;if(model){mixer.stopAllAction();scene.remove(model);model.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of [].concat(o.material))m.dispose();}});}model=g.scene;clips=g.animations;model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});scene.add(model);mixer=new T.AnimationMixer(model);playClip();fit();}catch(e){$('#status').textContent='Unable to load model';console.error(e);}}
$('#character').onchange=load;$('#clip').onchange=playClip;$('#restart').onclick=playClip;$('#play').onclick=()=>{if(action?.paused){playClip();return;}playing=!playing;$('#play').textContent=playing?'Pause':'Play';};$('#timeline').oninput=e=>{if(!action)return;playing=false;$('#play').textContent='Play';action.paused=false;action.time=Number(e.target.value)*action.getClip().duration;mixer.update(0);};
const clock=new T.Clock();function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);if(mixer&&playing)mixer.update(dt*Number($('#speed').value));if(action){$('#timeline').value=action.time/action.getClip().duration;$('#time').textContent=`${action.time.toFixed(2)} / ${action.getClip().duration.toFixed(2)} s`;if(action.paused&&playing){playing=false;$('#play').textContent='Play';}}renderer.render(scene,camera);}load();frame();
window.animationStudy={get state(){return {character:$('#character').value,clip:action?.getClip().name,time:action?.time,duration:action?.getClip().duration,playing,clips:clips?.map(c=>c.name),camera:camera.position.toArray(),target:orbit.target.toArray()};},scene,camera};
const toolbar=$('header');function dock(){for(const id of ['#ranch-view-sharing','#app-settings-toggle']){const b=$(id);if(b&&b.parentElement!==toolbar)toolbar.append(b);}}new MutationObserver(dock).observe(document.body,{childList:true,subtree:true});dock();
